type SeedExercise = {
  topicSlug: string;
  difficulty: Difficulty;
  type: ExerciseType;
  prompt: string;
  instructions: string;
  questionData: object;
  correctAnswer: object;
  explanationCorrect: string;
  explanationWrong: string;
  ruleSummary: string;
  extraExample: string;
};


const VALID_DIFFICULTIES: Difficulty[] = ['intermediate', 'advanced'];
const VALID_TYPES: ExerciseType[] = ['multiple_choice', 'fill_blank', 'error_correction', 'mini_production'];
const REQUIRED_FIELDS = [
  'topicSlug',
  'difficulty',
  'type',
  'prompt',
  'instructions',
  'questionData',
  'correctAnswer',
  'explanationCorrect',
  'explanationWrong',
  'ruleSummary',
  'extraExample',
] as const;

function validateSeedData() {
  const topicSlugs = new Set(topics.map(([slug]) => slug));

  for (const [index, ex] of exercises.entries()) {
    for (const key of REQUIRED_FIELDS) {
      const value = (ex as Record<string, unknown>)[key];
      if (value === undefined || value === null || value === '') {
        throw new Error(`Exercise #${index + 1} is missing required field: ${key}`);
      }
    }

    if (!topicSlugs.has(ex.topicSlug)) {
      throw new Error(`Exercise #${index + 1} references unknown topic slug: ${ex.topicSlug}`);
    }

    if (!VALID_DIFFICULTIES.includes(ex.difficulty)) {
      throw new Error(`Exercise #${index + 1} has invalid difficulty: ${ex.difficulty}`);
    }

    if (!VALID_TYPES.includes(ex.type)) {
      throw new Error(`Exercise #${index + 1} has invalid type: ${ex.type}`);
    }
  }

  const perTopicCount = new Map<string, number>();
  for (const ex of exercises) {
    perTopicCount.set(ex.topicSlug, (perTopicCount.get(ex.topicSlug) ?? 0) + 1);
  }

  for (const [slug] of topics) {
    if (!perTopicCount.has(slug)) {
      // topic can still be valid with zero exercises, but report clearly in seed logs
      console.warn(`Warning: topic "${slug}" has 0 seeded exercises.`);
    }
  }
}


