async function main() {
  validateSeedData();
  await prisma.attempt.deleteMany();
  await prisma.studySession.deleteMany();
  await prisma.dailyAssignmentHistory.deleteMany();
  await prisma.topicStats.deleteMany();
  await prisma.exercise.deleteMany();
  await prisma.topic.deleteMany();
  await prisma.appSettings.deleteMany();


  await prisma.appSettings.upsert({
    where: { id: 1 },
    create: { id: 1, defaultDailyTopics: 3, intensiveMode: false },
    update: {},
  });

  const createdTopics = new Map<string, number>();

  for (const [slug, name, description, cefrRange] of topics) {
    const topic = await prisma.topic.create({
      data: { slug, name, description, cefrRange, isActive: true },
    });
    createdTopics.set(slug, topic.id);

    await prisma.topicStats.create({ data: { topicId: topic.id } });
  }

  for (const ex of exercises) {
    await prisma.exercise.create({
      data: {
        topicId: createdTopics.get(ex.topicSlug)!,
        difficulty: ex.difficulty,
        type: ex.type,
        prompt: ex.prompt,
        instructions: ex.instructions,
        questionData: serializeJson(ex.questionData),
        correctAnswer: serializeJson(ex.correctAnswer),
        explanationCorrect: ex.explanationCorrect,
        explanationWrong: ex.explanationWrong,
        ruleSummary: ex.ruleSummary,
        extraExample: ex.extraExample,
        tags: serializeJson([ex.topicSlug, ex.difficulty, ex.type]),
        sourceType: 'seeded',
        isActive: true,
      },
    });
  }

  if (exercises.length !== 120) throw new Error(`Expected 120 exercises but found ${exercises.length}`);
  console.log(`Seed complete: ${topics.length} topics, ${exercises.length} exercises.`);
}

main()
  .catch((error) => {
    console.error(error);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
